"""Artico Chapter 08: reproducible 1800×900 transparent PNG illustrations.

The self-contained compressed drawing source is expanded locally at build
time; no network artwork or old placeholder assets are used.
"""
import base64
import zlib

_SOURCE = ""
exec(zlib.decompress(base64.b64decode(_SOURCE)).decode("utf-8"), {"__name__": "__main__", "__file__": __file__})
